<?php
require_once __DIR__ . '/../../config/response.php'; require_once __DIR__ . '/../../config/security.php';
header('Cache-Control: no-store'); $pdo=Database::getInstance(); $input=$_SERVER['REQUEST_METHOD']==='POST'?getJsonInput():$_GET; $session=validateSession($pdo,getBearerToken()?:($input['token']??''),15); if(!$session['valid']||!empty($session['is_2fa_pending'])) jsonResponse(['success'=>false,'error'=>'Please sign in to continue.'],401); $uid=(int)$session['user']['id'];
$stmt=$pdo->prepare("SELECT pl.uuid,pl.public_token,pl.title,pl.description,pl.amount,pl.currency_code,pl.status,pl.expires_at,pl.created_at,COALESCE(SUM(CASE WHEN p.status='succeeded' THEN t.amount ELSE 0 END),0) paid_amount,COUNT(p.id) payment_count FROM payment_links pl LEFT JOIN payments p ON p.payment_link_id=pl.id LEFT JOIN transactions t ON t.id=p.transaction_id WHERE pl.user_id=? GROUP BY pl.id ORDER BY pl.created_at DESC LIMIT 100"); $stmt->execute([$uid]); jsonResponse(['success'=>true,'links'=>$stmt->fetchAll()]);
